     1|/**
     2| * IVX Business Context Engine
     3| *
     4| * BLOCK 2 — every Owner / public chat conversation must load IVX business
     5| * context automatically, so questions like "What is Casa Rosario?" are answered
     6| * from real business data without the caller having to trigger a manual lookup.
     7| *
     8| * It assembles five context buckets into a single model-readable block:
     9| *   1. Projects        — published rows from the authoritative `jv_deals` source.
    10| *   2. Deal data       — per-deal economics (price / ROI / timeline / min ownership).
    11| *   3. Company context — who IVX is and what the platform does.
    12| *   4. Landing context — the public site the projects are rendered on.
    13| *   5. Owner context   — the owner identity the assistant reports to.
    14| *
    15| * The projects/deal buckets are LIVE (read-only over Supabase REST). The
    16| * company / landing / owner buckets are static config + env. The block is built
    17| * defensively so a failed project read never blocks the conversation — it just
    18| * states the honest reason instead of fabricating data.
    19| */
    20|import { readLandingProjects, type ProjectDataResult } from './ivx-project-data';
    21|
    22|function readTrimmed(value: unknown): string {
    23|  return typeof value === 'string' ? value.trim() : '';
    24|}
    25|
    26|export type CompanyContext = {
    27|  name: string;
    28|  description: string;
    29|  model: string;
    30|};
    31|
    32|export type LandingContext = {
    33|  url: string;
    34|  description: string;
    35|};
    36|
    37|export type OwnerContext = {
    38|  email: string | null;
    39|  role: string;
    40|};
    41|
    42|export type BusinessContext = {
    43|  loadedAt: string;
    44|  projects: ProjectDataResult;
    45|  company: CompanyContext;
    46|  landing: LandingContext;
    47|  owner: OwnerContext;
    48|};
    49|
    50|/** Static company identity used to ground every conversation. */
    51|export function getCompanyContext(): CompanyContext {
    52|  return {
    53|    name: 'IVX Holding',
    54|    description:
    55|      'IVX is a real-estate joint-venture platform that makes property investing easier to understand and participate in. Investors review a deal (location, price, expected ROI, timeline, ownership minimum), then participate after reading the actual documents.',
    56|    model: 'Real-estate joint ventures (JV deals) with fractional ownership and defined return assumptions.',
    57|  };
    58|}
    59|
    60|/** Public landing context (the site the projects are rendered on). */
    61|export function getLandingContext(): LandingContext {
    62|  const url = readTrimmed(process.env.IVX_LANDING_URL) || 'https://ivxholding.com';
    63|  return {
    64|    url,
    65|    description: `The public landing page (${url}) renders the published projects client-side from the authoritative jv_deals source.`,
    66|  };
    67|}
    68|
    69|/** Owner identity the assistant reports to. */
    70|export function getOwnerContext(): OwnerContext {
    71|  const email =
    72|    readTrimmed(process.env.EXPO_PUBLIC_OWNER_EMAIL) ||
    73|    readTrimmed(process.env.OWNER_REPAIR_EMAIL) ||
    74|    null;
    75|  return {
    76|    email,
    77|    role: 'IVX owner / operator',
    78|  };
    79|}
    80|
    81|/**
    82| * Load the full business context. Live projects/deal data are fetched read-only;
    83| * company / landing / owner are resolved from config + env. Never throws — a
    84| * failed project read is captured in `projects.ok=false` with an honest reason.
    85| */
    86|export async function loadBusinessContext(): Promise<BusinessContext> {
    87|  let projects: ProjectDataResult;
